package com.metaarch.catalog.product;
import java.net.URI; import java.util.UUID; import com.metaarch.catalog.common.PageResponse; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/products") public class ProductController {
 private final ProductService service; private final com.metaarch.catalog.config.CatalogAccess access; public ProductController(ProductService s,com.metaarch.catalog.config.CatalogAccess access){service=s;this.access=access;}
 @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','GLOBAL_ADMIN','SUPER_ADMIN')")
 @PostMapping ResponseEntity<ProductResponse> create(@Valid @RequestBody ProductRequest r,Authentication auth){requireGlobalProductScope(auth,r.globalProduct());ProductResponse v=service.create(r);return ResponseEntity.created(URI.create("/api/v1/products/"+v.id())).body(v);}
 @GetMapping PageResponse<ProductResponse> list(@RequestParam(required=false) UUID categoryId,@RequestParam(required=false) ProductStatus status,@RequestParam(required=false) String search,@RequestParam(required=false) String q,@RequestParam(required=false) Boolean globalProduct,@RequestParam(required=false) String storeId,@PageableDefault(size=50,sort="name") Pageable pageable,Authentication authentication){String term=search!=null?search:q;if(authentication!=null&&authentication.getAuthorities().stream().anyMatch(a->"ROLE_LOCATION_ADMIN".equals(a.getAuthority())))return service.listForLocation(authentication,categoryId,status,term,pageable);if(access.storeManager(authentication)){access.requireStore(authentication,storeId);return service.listForStore(storeId,categoryId,status,term,pageable);}return service.list(categoryId,status,term,access.globalAdmin(authentication)?true:globalProduct,pageable);}
 @org.springframework.security.access.prepost.PreAuthorize("@catalogAccess.canReadProduct(authentication,#id)") @GetMapping("/{id}") ProductResponse get(@PathVariable UUID id){return service.get(id);}
 @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','GLOBAL_ADMIN','SUPER_ADMIN')")
 @PutMapping("/{id}") ProductResponse update(@PathVariable UUID id,@Valid @RequestBody ProductRequest r,Authentication auth){requireGlobalProductScope(auth,service.get(id).globalProduct());requireGlobalProductScope(auth,r.globalProduct());return service.update(id,r);}
 @org.springframework.security.access.prepost.PreAuthorize("hasAnyRole('ADMIN','GLOBAL_ADMIN','SUPER_ADMIN')")
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id,Authentication auth){requireGlobalProductScope(auth,service.get(id).globalProduct());service.delete(id);}
 private void requireGlobalProductScope(Authentication auth,Boolean isGlobalProduct){if(access.globalAdmin(auth)&&!Boolean.TRUE.equals(isGlobalProduct))throw new org.springframework.security.access.AccessDeniedException("Global Admin can manage products assigned to the Global Store only.");}
}
